import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for k,v in G.items():
    print(k, len(v), len(v[0]))

def shapes(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; cells=[]
                while st:
                    a,b=st.pop()
                    if a<0 or b<0 or a>=H or b>=W or seen[a][b] or g[a][b]!=col: continue
                    seen[a][b]=True; cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y]==col and not seen[x][y]: st.append((x,y))
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                out.append((col,min(rs),min(cs),max(rs)-min(rs)+1,max(cs)-min(cs)+1,cells))
    return out
for k in ['Demo pair 1 input','Test input']:
    print(k,[(c,r0,c0,h,w) for c,r0,c0,h,w,_ in shapes(G[k])])

D=G['Demo pair 1 input']; O=G['Demo pair 1 output']
for c,r0,c0,h,w,cells in shapes(D):
