def cands(g):
    H,W=len(g),len(g[0]); out=[]
    for r0 in range(H-2):
        for c0 in range(W-2):
            blk=[g[r0+i][c0+j] for i in range(3) for j in range(3)]
            if len(set(blk))==3 and 0 not in blk:
                out.append((r0,c0,blk))
    return out
